//! Frozen-format parity for the paint strings.
//!
//! `paintLogic.js`, `levelProgress.js` and the Jive level rows are all served
//! by `load/paint_jive.rs`, and every string they produce must match the
//! reference rs2b0t sources byte for byte
//! (`reference/rs2b0t-00d39a17e0/src/bot/paint/{paintLogic,levelProgress}.ts`).
//! The expected column below was generated by running those sources under bun
//! (`String(n)` round-trips NaN and Infinity instead of collapsing them), and
//! the argument column is a JS expression, so an `undefined` argument stays
//! distinct from `null`.

use script::{LoadIsolate, LoadShape};

/// Every formatter the paint shim exports, re-exported for probing.
const BOT: &str = r#"
import { fmtDuration, fmtXpHr, paintSkillShort } from '../../paint/paintLogic.js';
import { xpAtLevel, levelProgress, etaHours, levelRow } from '../../paint/levelProgress.js';
globalThis.__f12 = { fmtDuration, fmtXpHr, paintSkillShort, xpAtLevel, levelProgress, etaHours, levelRow };
export default class T extends LoopingBot {}
"#;

fn spawn() -> LoadIsolate {
    LoadIsolate::spawn(BOT.to_string(), LoadShape::CompatClass, vec![]).expect("bot loads")
}

fn probe_str(iso: &LoadIsolate, expr: &str) -> String {
    iso.probe(expr)
        .unwrap_or_else(|e| panic!("probe {expr}: {e}"))
        .as_str()
        .unwrap_or_else(|| panic!("probe {expr} did not return a string"))
        .to_string()
}

