#[test]
fn fmt_duration_matches_the_frozen_reference() {
    let iso = spawn();
    for (mins, want) in DURATION {
        let got = probe_str(&iso, &format!("String(__f12.fmtDuration({mins}))"));
        assert_eq!(got, *want, "fmtDuration({mins})");
    }
    iso.join();
}

#[test]
fn fmt_xp_hr_matches_the_frozen_reference() {
    let iso = spawn();
    for (gained, mins, want) in RATE {
        let got = probe_str(&iso, &format!("String(__f12.fmtXpHr({gained}, {mins}))"));
        assert_eq!(got, *want, "fmtXpHr({gained}, {mins})");
    }
    iso.join();
}

#[test]
fn paint_skill_short_matches_the_frozen_reference() {
    let iso = spawn();
    for (skill, want) in SKILL {
        let got = probe_str(&iso, &format!("String(__f12.paintSkillShort('{skill}'))"));
        assert_eq!(got, *want, "paintSkillShort({skill})");
    }
    iso.join();
}

#[test]
fn xp_at_level_matches_the_frozen_reference() {
    let iso = spawn();
    for (level, want) in XP_AT_LEVEL {
        let got = probe_str(&iso, &format!("String(__f12.xpAtLevel({level}))"));
        assert_eq!(got, *want, "xpAtLevel({level})");
    }
    iso.join();
}

#[test]
fn level_progress_matches_the_frozen_reference() {
    let iso = spawn();
    for (level, xp, want) in PROGRESS {
        let expr = format!(
            "(() => {{ const p = __f12.levelProgress({level}, {xp}); return [String(p.level), String(p.fraction), String(p.remaining)].join('|'); }})()"
        );
        let got = probe_str(&iso, &expr);
        assert_eq!(got, *want, "levelProgress({level}, {xp})");
    }
    iso.join();
}

#[test]
fn eta_hours_matches_the_frozen_reference() {
    let iso = spawn();
    for (remaining, rate, want) in ETA {
        let got = probe_str(
            &iso,
            &format!("String(__f12.etaHours({remaining}, {rate}))"),
        );
        assert_eq!(got, *want, "etaHours({remaining}, {rate})");
    }
    iso.join();
}

